head.script:
scwin.screenId = "jldstf30013";

///////// 1. 변수 및 선언 영역 /////////

scwin.grd_List_Tab1 = $c.util.getComponent('grd_List_Tab1');


scwin.btn_Save = $c.util.getComponent('btn_Save');

scwin.btn_Close = $c.util.getComponent('btn_Close');

scwin.index = '1';

scwin.winHight = undefined;

scwin.vScrenID = 'ULDSTF30013.gfm';

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.index = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin fn_Init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (js_duty_chrg === 'Y') {
        scwin.gDuty = 'Y';
    }
    if ((js_duty === "Y" || js_duty_chrg === "Y") || (scwin.gJobTitl === '06' || scwin.gJobTitl === '09')) {
        scwin.winHight = '620';
    } else {
        scwin.winHight = '620';
        $c.fil.showObj(scwin.btn_Close, false);
        $c.fil.showObj(scwin.btn_Save, false);
    }
    scwin.fn_Search('1');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        MxTab_1.activeindex = "1";
        scwin.init();
        scwin.resizeToWin();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_Grid_Tab1 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Grid_Tab1')) : $c.util.getComponent('dts_Grid_Tab1');

scwin.dts_Grid_Tab2 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Grid_Tab2')) : $c.util.getComponent('dts_Grid_Tab2');

scwin.gDepCd = undefined; try { scwin.gDepCd = /* sdd-asis-lifecycle:begin gDepCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("depCd")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

scwin.gEmpNo = undefined; try { scwin.gEmpNo = /* sdd-asis-lifecycle:begin gEmpNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("empNo")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

scwin.gLdMktTp = undefined; try { scwin.gLdMktTp = /* sdd-asis-lifecycle:begin gLdMktTp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("market")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

scwin.gJobTitl = undefined; try { scwin.gJobTitl = /* sdd-asis-lifecycle:begin gJobTitl — as-is 원문 본문(전환 이관 · 포팅 적용됨) */js_jobtitl/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

scwin.gDuty = undefined; try { scwin.gDuty = /* sdd-asis-lifecycle:begin gDuty — as-is 원문 본문(전환 이관 · 포팅 적용됨) */js_duty/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30013' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf30013.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
