        /* sdd-asis-lifecycle:begin btn_Excel_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.fil.doLogSave(scwin.vScrenID, $c.fil.SCREN_PROCS_TP_CD_07);
        scwin.grd_List_Tab1.GridToExcel("일정확인", "", "2");
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.btn_Excel_onclick' }); }
};

/**
