*/
scwin.dts_Grid_Tab1_onloadcompleted = function (rowcount) {
    /* sdd-asis-lifecycle:begin dts_Grid_Tab1_onloadcompleted — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    void 0;
    /* sdd-asis-lifecycle:end */
};

