*/
scwin.dts_Grid_Tab1_onloaderror = function () {
    /* sdd-asis-lifecycle:begin dts_Grid_Tab1_onloaderror — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.fil.alert_error(scwin.dts_Grid_Tab1);
