*/
scwin.dts_Grid_Tab2_onloadcompleted = function (rowcount) {
    /* sdd-asis-lifecycle:begin dts_Grid_Tab2_onloadcompleted — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    void 0;
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.dts_Grid_Tab2_onloaderror
 * @author Inswave
 * @date 2026. 09. 29
