 * @hidden N
*/
scwin.dts_Grid_Tab2_onloaderror = function () {
    /* sdd-asis-lifecycle:begin dts_Grid_Tab2_onloaderror — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.fil.alert_error(scwin.dts_Grid_Tab2);
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
