*/
scwin.btn_Save_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Save_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_Save();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.btn_Save_onclick' }); }
};

