    try {
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.frame.CloseFrame();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.btn_Close_onclick' }); }
};

/**
 * @event
 * @name scwin.MxTab_1_onselchanged
 * @author Inswave
 * @date 2026. 09. 29
 * @param nIndex
 * @returns
 * @hidden N
*/
scwin.MxTab_1_onselchanged = function (nIndex) {
    try {
        /* sdd-asis-lifecycle:begin MxTab_1_onselchanged — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (nIndex == 1) {
            scwin.fn_Search('1');
        } else {
            if (nIndex == 2) {
                scwin.fn_Search('2');
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30013.MxTab_1_onselchanged' }); }
};

/**
 * @method
 * @name scwin.trs_Save_onsuccess
 * @author Inswave
 * @date 2026. 09. 29
 * @description 알림을 띄운다 외
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onsuccess = async function () {
    /* sdd-asis-lifecycle:begin trs_Save_onsuccess — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert("성공적으로 처리 되었습니다.");
    scwin.fn_Search(scwin.index);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.trs_Save_onfail
 * @author Inswave
 * @date 2026. 09. 29
 * @description 알림을 띄운다
 * @param
 * @returns
 * @hidden N
*/
scwin.trs_Save_onfail = async function () {
    /* sdd-asis-lifecycle:begin trs_Save_onfail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert('trs_Save.OnFail() :' + trs_Save.ErrorMsg);
    /* sdd-asis-lifecycle:end */
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_script_dts_Grid_Tab1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_Grid_Tab1 = async function () {
    $c.util.getComponent("dma_scriptDts_Grid_Tab1Req").set("DUTY_YN", "Y");
    $c.util.getComponent("dma_scriptDts_Grid_Tab1Req").set("DUTY_YN", "N");
    $c.util.getComponent("dma_scriptDts_Grid_Tab1Req").set("SCREN_ID", 'ULDSTF30013.gfm');
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — LD_MKT_TP_CD, DEP_CD, EMP_NO, JOB_TITL, GUBUN, SCREN_PROCES_TP_CD", unresolved: "query_param:LD_MKT_TP_CD,DEP_CD,EMP_NO,JOB_TITL,GUBUN,SCREN_PROCES_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_Grid_Tab1",
        method: "post",
        action: "/DisclosureSchedule.do",
        ref: "dma_scriptDts_Grid_Tab1Req",
        target: "dts_Grid_Tab1=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_Grid_Tab1_onloaderror'] === 'function') ? scwin['dts_Grid_Tab1_onloaderror'] : (typeof scwin['dts_Grid_Tab1_onfail'] === 'function') ? scwin['dts_Grid_Tab1_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_Grid_Tab1_onloadcompleted'] === 'function') ? scwin['dts_Grid_Tab1_onloadcompleted'] : ((typeof scwin['dts_Grid_Tab1_onsuccess'] === 'function') ? scwin['dts_Grid_Tab1_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_Grid_Tab1'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30013.tx_script_dts_Grid_Tab1" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.sbm_trs_Save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.sbm_trs_Save = async function () {
    const sbmOptions = {
        id: "sbm_trs_Save",
        method: "post",
        action: "/DisclosureSchedule.do",
        ref: "dma_sbmTrs_SaveReq",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['trs_Save_onloaderror'] === 'function') ? scwin['trs_Save_onloaderror'] : (typeof scwin['trs_Save_onfail'] === 'function') ? scwin['trs_Save_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['trs_Save_onloadcompleted'] === 'function') ? scwin['trs_Save_onloadcompleted'] : ((typeof scwin['trs_Save_onsuccess'] === 'function') ? scwin['trs_Save_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('trs_Save'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf30013.sbm_trs_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.resizeToWin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.resizeToWin = function () {
    /* sdd-asis-lifecycle:begin fn_resizeToWin — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.frame.Width = 635;
    $c.frame.Height = scwin.winHight;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchMain
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchMain = function () {
    /* sdd-asis-lifecycle:begin fn_SearchMain — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (MxTab_1.selectedIndex == 1) {
        scwin.fn_Search('1');
    } else {
        if (MxTab_1.selectedIndex == 2) {
            scwin.fn_Search('2');
        }
    }
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_Search = scwin.tx_script_dts_Grid_Tab1;

scwin.fn_Save = scwin.sbm_trs_Save;
